 boolean bounds=true,centers=true;for(int mode=0;mode<2;mode++){AppTheme.select(mode);for(float font:new float[]{1,1.3f,2})for(int width:new int[]{48,51,60})for(float ev:new float[]{-3,-2.9f,-.1f,0,.1f,2.9f,3}){h=new H();h.c.resources.metrics.scaledDensity=font;int height=UiSpec.captureHeight(font);h.wheel.size(width,height);h.wheel.set(ev);Canvas canvas=new Canvas();h.wheel.onDraw(canvas);for(float[] b:canvas.textBounds)bounds&=b[0]>=0&&b[1]>=0&&b[2]<=width&&b[3]<=height;int idx=canvas.texts.indexOf(ExposureValue.label(ev));centers&=idx>=0&&Math.abs((canvas.textBounds.get(idx)[1]+canvas.textBounds.get(idx)[3])/2-height/2f)<.1f&&canvas.texts.contains("EV");}}
